class IndependentDailyStrategiesAlgorithm(QCAlgorithm):
    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1_000_000)

        self.tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        self.symbols = {
            ticker: self.add_equity(ticker, Resolution.DAILY).symbol
            for ticker in self.tickers
        }

        self.spy_sma = SimpleMovingAverage(100)
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.WILDERS)
        self.previous_close = {ticker: None for ticker in self.tickers}
        self.previous_spy_close = None
        self.previous_spy_sma = None
        self.aapl_red_streak = 0

        self.spy_lot = 0
        self.aapl_lot = 0
        self.rsi_sell_threshold = 70

        self.set_warm_up(101, Resolution.DAILY)

    def on_data(self, data: Slice):
        bars = {}
        for ticker, symbol in self.symbols.items():
            if symbol in data.bars:
                bars[ticker] = data.bars[symbol]

        # Market-state quantities continue to update even on incomplete slices.
        if "SPY" in bars:
            spy_close = bars["SPY"].close
            self.spy_sma.update(data.time, spy_close)

        if "AAPL" in bars:
            aapl_close = bars["AAPL"].close
            old_aapl_close = self.previous_close["AAPL"]
            self.aapl_rsi.update(data.time, aapl_close)
            if old_aapl_close is not None and aapl_close < old_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

        complete_slice = len(bars) == len(self.tickers)
        indicators_ready = self.spy_sma.is_ready and self.aapl_rsi.is_ready

        if complete_slice and indicators_ready and not self.is_warming_up:
            self._evaluate_spy(bars["SPY"].close)
            self._evaluate_aapl(bars["AAPL"].close)

        if "SPY" in bars and self.spy_sma.is_ready:
            self.previous_spy_close = bars["SPY"].close
            self.previous_spy_sma = self.spy_sma.current.value

        for ticker, bar in bars.items():
            self.previous_close[ticker] = bar.close

    def _evaluate_spy(self, close):
        if self.previous_spy_close is None or self.previous_spy_sma is None:
            return

        sma = self.spy_sma.current.value
        crosses_above = (
            self.previous_spy_close <= self.previous_spy_sma and close > sma
        )
        crosses_below = (
            self.previous_spy_close >= self.previous_spy_sma and close < sma
        )

        # Sells are evaluated before buys.
        if self.spy_lot > 0 and crosses_below:
            self.market_order(self.symbols["SPY"], -self.spy_lot)
            self.spy_lot = 0
        elif self.spy_lot == 0 and crosses_above:
            target_value = 0.40 * self.portfolio.total_portfolio_value
            quantity = int(target_value // close)
            if quantity > 0:
                self.market_order(self.symbols["SPY"], quantity)
                self.spy_lot = quantity

    def _evaluate_aapl(self, close):
        # Sells are evaluated before buys.
        if self.aapl_lot > 0 and self.aapl_rsi.current.value > self.rsi_sell_threshold:
            self.market_order(self.symbols["AAPL"], -self.aapl_lot)
            self.aapl_lot = 0
        elif self.aapl_lot == 0 and self.aapl_red_streak >= 3:
            if self.portfolio.cash >= 20_000:
                quantity = int(20_000 // close)
                if quantity > 0:
                    self.market_order(self.symbols["AAPL"], quantity)
                    self.aapl_lot = quantity

