class IndependentSpyAaplStrategies(QCAlgorithm):
    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.add_equity(
                ticker, Resolution.DAILY
            ).symbol

        self.spy_sma = SimpleMovingAverage(100)
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.WILDERS)

        self.spy_previous_close = None
        self.spy_previous_sma = None
        self.aapl_previous_close = None
        self.aapl_red_streak = 0

        self.spy_lot = 0
        self.aapl_lot = 0
        self.spy_pending = False
        self.aapl_pending = False
        self.rsi_threshold = 70.0

    def on_data(self, data: Slice):
        bars = {}
        for ticker, symbol in self.symbols.items():
            if data.bars.contains_key(symbol):
                bars[ticker] = data.bars[symbol]

        # Market-state quantities continue to consume every available bar, even
        # when a missing subscription causes all trading rules to be skipped.
        spy = bars.get("SPY")
        if spy is not None:
            self.spy_sma.update(self.time, spy.close)

        aapl = bars.get("AAPL")
        if aapl is not None:
            if self.aapl_previous_close is not None:
                if aapl.close < self.aapl_previous_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.aapl_rsi.update(self.time, aapl.close)

        all_bars_present = len(bars) == len(self.symbols)
        if all_bars_present:
            self._evaluate_spy(spy)
            self._evaluate_aapl(aapl)

        if spy is not None:
            self.spy_previous_close = spy.close
            if self.spy_sma.is_ready:
                self.spy_previous_sma = self.spy_sma.current.value
            else:
                self.spy_previous_sma = None
        if aapl is not None:
            self.aapl_previous_close = aapl.close

    def _evaluate_spy(self, bar):
        if (
            not self.spy_sma.is_ready
            or self.spy_previous_close is None
            or self.spy_previous_sma is None
            or self.spy_pending
        ):
            return

        close = float(bar.close)
        sma = float(self.spy_sma.current.value)

        # Sells are evaluated before buys, and each condition is restricted to
        # the state of this strategy's private lot.
        if self.spy_lot > 0:
            crossed_below = (
                self.spy_previous_close >= self.spy_previous_sma
                and close < sma
            )
            if crossed_below:
                self.spy_pending = True
                self.market_order(self.symbols["SPY"], -self.spy_lot)
            return

        crossed_above = (
            self.spy_previous_close <= self.spy_previous_sma and close > sma
        )
        if crossed_above:
            quantity = math.floor(
                0.40 * float(self.portfolio.total_portfolio_value) / close
            )
            if quantity > 0:
                self.spy_pending = True
                self.market_order(self.symbols["SPY"], quantity)

    def _evaluate_aapl(self, bar):
        if not self.aapl_rsi.is_ready or self.aapl_pending:
            return

        if self.aapl_lot > 0:
            if float(self.aapl_rsi.current.value) > self.rsi_threshold:
                self.aapl_pending = True
                self.market_order(self.symbols["AAPL"], -self.aapl_lot)
            return

        if self.aapl_red_streak >= 3:
            cash_to_invest = 20_000.0
            if float(self.portfolio.cash) >= cash_to_invest:
                quantity = math.floor(cash_to_invest / float(bar.close))
                if quantity > 0:
                    self.aapl_pending = True
                    self.market_order(self.symbols["AAPL"], quantity)

    def on_order_event(self, order_event: OrderEvent):
        if order_event.status not in (OrderStatus.FILLED, OrderStatus.PARTIALLY_FILLED):
            if order_event.status in (
                OrderStatus.CANCELED,
                OrderStatus.INVALID,
            ):
                symbol = order_event.symbol
                if symbol == self.symbols["SPY"]:
                    self.spy_pending = False
                elif symbol == self.symbols["AAPL"]:
                    self.aapl_pending = False
            return

        fill_quantity = int(order_event.fill_quantity)
        symbol = order_event.symbol
        if symbol == self.symbols["SPY"]:
            self.spy_lot += fill_quantity
            if order_event.status == OrderStatus.FILLED:
                self.spy_pending = False
        elif symbol == self.symbols["AAPL"]:
            self.aapl_lot += fill_quantity
            if order_event.status == OrderStatus.FILLED:
                self.aapl_pending = False

