class IndependentSpyAaplStrategies(QCAlgorithm):
    RSI_SELL_THRESHOLD = 70

    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1_000_000)

        self.tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        self.symbols = {
            ticker: self.add_equity(ticker, Resolution.DAILY).symbol
            for ticker in self.tickers
        }

        self.spy_closes = deque(maxlen=101)
        self.aapl_previous_close = None
        self.aapl_red_streak = 0
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.WILDERS)

        self.spy_lot = 0
        self.aapl_lot = 0
        self.pending_orders = {}
        self.pending_strategy = set()

    def on_data(self, data):
        bars = {}
        for ticker, symbol in self.symbols.items():
            if data.bars.contains_key(symbol):
                bars[ticker] = data.bars[symbol]

        # Market-state quantities continue to advance whenever their own bar exists.
        if "SPY" in bars:
            self.spy_closes.append(float(bars["SPY"].close))

        if "AAPL" in bars:
            aapl_bar = bars["AAPL"]
            aapl_close = float(aapl_bar.close)
            if self.aapl_previous_close is not None:
                if aapl_close < self.aapl_previous_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.aapl_previous_close = aapl_close
            self.aapl_rsi.update(aapl_bar.end_time, aapl_bar.close)

        # A missing bar for even one subscription suppresses every rule for the day.
        if len(bars) != len(self.symbols):
            return

        # Sells are evaluated before buys.
        self._evaluate_spy_sell()
        self._evaluate_aapl_sell()
        self._evaluate_spy_buy()
        self._evaluate_aapl_buy(bars["AAPL"])

    def _evaluate_spy_sell(self):
        if self.spy_lot <= 0 or "SPY" in self.pending_strategy:
            return
        if self._spy_crossed_below_sma():
            self._submit_lot_order("SPY", -self.spy_lot)

    def _evaluate_aapl_sell(self):
        if self.aapl_lot <= 0 or "AAPL" in self.pending_strategy:
            return
        if self.aapl_rsi.is_ready and self.aapl_rsi.current.value > self.RSI_SELL_THRESHOLD:
            self._submit_lot_order("AAPL", -self.aapl_lot)

    def _evaluate_spy_buy(self):
        if self.spy_lot != 0 or "SPY" in self.pending_strategy:
            return
        if self._spy_crossed_above_sma():
            quantity = self.calculate_order_quantity(self.symbols["SPY"], 0.40)
            if quantity > 0:
                self._submit_lot_order("SPY", quantity)

    def _evaluate_aapl_buy(self, bar):
        if self.aapl_lot != 0 or "AAPL" in self.pending_strategy:
            return
        if not self.aapl_rsi.is_ready or self.aapl_red_streak < 3:
            return

        allocation = 20_000
        if self.portfolio.cash < allocation:
            return
        quantity = floor(allocation / float(bar.close))
        if quantity > 0:
            self._submit_lot_order("AAPL", quantity)

    def _spy_crossed_above_sma(self):
        if len(self.spy_closes) < 101:
            return False
        closes = list(self.spy_closes)
        previous_sma = sum(closes[:100]) / 100
        current_sma = sum(closes[1:]) / 100
        return closes[-2] <= previous_sma and closes[-1] > current_sma

    def _spy_crossed_below_sma(self):
        if len(self.spy_closes) < 101:
            return False
        closes = list(self.spy_closes)
        previous_sma = sum(closes[:100]) / 100
        current_sma = sum(closes[1:]) / 100
        return closes[-2] >= previous_sma and closes[-1] < current_sma

    def _submit_lot_order(self, ticker, quantity):
        ticket = self.market_order(self.symbols[ticker], quantity)
        self.pending_orders[ticket.order_id] = ticker
        self.pending_strategy.add(ticker)

    def on_order_event(self, order_event):
        ticker = self.pending_orders.get(order_event.order_id)
        if ticker is None:
            return

        if order_event.status in (OrderStatus.PARTIALLY_FILLED, OrderStatus.FILLED):
            if ticker == "SPY":
                self.spy_lot += int(order_event.fill_quantity)
            else:
                self.aapl_lot += int(order_event.fill_quantity)

        if order_event.status in (
            OrderStatus.FILLED,
            OrderStatus.CANCELED,
            OrderStatus.INVALID,
        ):
            self.pending_orders.pop(order_event.order_id, None)
            self.pending_strategy.discard(ticker)

