            ticker: deque(maxlen=101) for ticker in self.tickers
        }
        self.previous_close = {ticker: None for ticker in self.tickers}
        self.red_streak = {ticker: 0 for ticker in self.tickers}

        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.spy_lot = 0
        self.aapl_lot = 0

    def OnData(self, data: Slice):
        bars = {}
        for ticker, symbol in self.symbols.items():
            if data.Bars.ContainsKey(symbol):
                bar = data.Bars[symbol]
                bars[ticker] = bar
                close = bar.Close

                previous = self.previous_close[ticker]
                if previous is not None and close < previous:
                    self.red_streak[ticker] += 1
                else:
                    self.red_streak[ticker] = 0

                self.previous_close[ticker] = close
                self.close_history[ticker].append(close)

                if ticker == "AAPL":
                    self.aapl_rsi.Update(bar.EndTime, close)

        if len(bars) != len(self.tickers):
            return

        spy_crossed_above, spy_crossed_below = self._spy_sma_crosses()

        # All sell rules are evaluated before either strategy's buy rule.
        if self.spy_lot > 0 and spy_crossed_below:
            self.MarketOrder(self.symbols["SPY"], -self.spy_lot)
            self.spy_lot = 0

        if (
            self.aapl_lot > 0
            and self.aapl_rsi.IsReady
            and self.aapl_rsi.Current.Value > self.RSI_THRESHOLD
        ):
            self.MarketOrder(self.symbols["AAPL"], -self.aapl_lot)
            self.aapl_lot = 0

        if self.spy_lot == 0 and spy_crossed_above:
            quantity = self.CalculateOrderQuantity(self.symbols["SPY"], 0.40)
            if quantity > 0:
                self.MarketOrder(self.symbols["SPY"], quantity)
                self.spy_lot = quantity

        if self.aapl_lot == 0 and self.red_streak["AAPL"] >= 3:
            cash_to_invest = 20_000
            available_cash = self.Portfolio.CashBook["USD"].Amount
            if available_cash >= cash_to_invest:
                quantity = floor(cash_to_invest / bars["AAPL"].Close)
                if quantity > 0:
                    self.MarketOrder(self.symbols["AAPL"], quantity)
                    self.aapl_lot = quantity

    def _spy_sma_crosses(self):
        closes = self.close_history["SPY"]
        if len(closes) < 101:
            return False, False

        values = list(closes)
        yesterday_close = values[-2]
        today_close = values[-1]
        yesterday_sma = sum(values[:-1]) / 100
        today_sma = sum(values[1:]) / 100

        crossed_above = yesterday_close <= yesterday_sma and today_close > today_sma
        crossed_below = yesterday_close >= yesterday_sma and today_close < today_sma
        return crossed_above, crossed_below

