class ParallelSpyAaplStrategies(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy_closes = deque(maxlen=101)
        self.aapl_closes = deque(maxlen=4)
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)
        self.rsi_threshold = 70

        self.previous_spy_close = None
        self.previous_spy_sma = None
        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

    def OnData(self, data):
        bars = {}
        for ticker, symbol in self.symbols.items():
            if data.Bars.ContainsKey(symbol):
                bars[ticker] = data.Bars[symbol]

        spy = bars.get("SPY")
        if spy is not None:
            self.spy_closes.append(float(spy.Close))

        aapl = bars.get("AAPL")
        if aapl is not None:
            close = float(aapl.Close)
            self.aapl_closes.append(close)
            self.aapl_rsi.Update(data.Time, close)

        # A missing daily bar for any subscription suppresses every trade rule.
        if len(bars) != len(self.symbols):
            self._record_spy_cross_values(spy)
            return

        spy_close = float(spy.Close)
        spy_sma = self._current_spy_sma()
        aapl_close = float(aapl.Close)

        # Both independent strategies evaluate their sell rule before their buy rule.
        if self.strategy_a_shares > 0:
            if self._spy_crosses_below(spy_close, spy_sma):
                self.MarketOrder(self.symbols["SPY"], -self.strategy_a_shares)
                self.strategy_a_shares = 0
        elif self._spy_crosses_above(spy_close, spy_sma):
            quantity = self.CalculateOrderQuantity(self.symbols["SPY"], 0.40)
            if quantity > 0:
                self.MarketOrder(self.symbols["SPY"], quantity)
                self.strategy_a_shares = quantity

        if self.strategy_b_shares > 0:
            if self.aapl_rsi.IsReady and float(self.aapl_rsi.Current.Value) > self.rsi_threshold:
                self.MarketOrder(self.symbols["AAPL"], -self.strategy_b_shares)
                self.strategy_b_shares = 0
        elif len(self.aapl_closes) == self.aapl_closes.maxlen:
            closes = list(self.aapl_closes)
            red_for_three_days = all(
                closes[index] < closes[index - 1] for index in range(1, 4)
            )
            if red_for_three_days:
                available_cash = float(self.Portfolio.CashBook["USD"].Amount)
                if available_cash >= 20_000:
                    quantity = floor(20_000 / aapl_close)
                    if quantity > 0:
                        self.MarketOrder(self.symbols["AAPL"], quantity)
                        self.strategy_b_shares = quantity

        self.previous_spy_close = spy_close
        self.previous_spy_sma = spy_sma

    def _current_spy_sma(self):
        if len(self.spy_closes) < 100:
            return None
        closes = list(self.spy_closes)
        return sum(closes[-100:]) / 100

    def _record_spy_cross_values(self, spy):
        if spy is None:
            return
        self.previous_spy_close = float(spy.Close)
        self.previous_spy_sma = self._current_spy_sma()

    def _spy_crosses_above(self, close, sma):
        return (
            sma is not None
            and self.previous_spy_sma is not None
            and self.previous_spy_close <= self.previous_spy_sma
            and close > sma
        )

    def _spy_crosses_below(self, close, sma):
        return (
            sma is not None
            and self.previous_spy_sma is not None
            and self.previous_spy_close >= self.previous_spy_sma
            and close < sma
        )

