class IndependentDailyStrategiesAlgorithm(QCAlgorithm):
    """Two independent, close-of-day strategies with separately tracked lots."""

    RSI_SELL_THRESHOLD = 70

    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.add_equity(ticker, Resolution.DAILY).symbol

        self.spy_closes = RollingWindow[float](101)
        self.aapl_previous_close = None
        self.aapl_red_streak = 0
        self.aapl_rsi = self.rsi(
            self.symbols["AAPL"],
            14,
            MovingAverageType.WILDERS,
            Resolution.DAILY,
        )

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

    def on_data(self, data: Slice):
        spy_symbol = self.symbols["SPY"]
        aapl_symbol = self.symbols["AAPL"]

        # State continues to consume every available trading bar, even on a day
        # when another subscription is absent and trading rules must be skipped.
        if data.bars.contains_key(spy_symbol):
            self.spy_closes.add(float(data.bars[spy_symbol].close))

        if data.bars.contains_key(aapl_symbol):
            aapl_close = float(data.bars[aapl_symbol].close)
            if self.aapl_previous_close is not None:
                if aapl_close < self.aapl_previous_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.aapl_previous_close = aapl_close

        # The system is evaluated only when all five subscriptions have a bar.
        if any(not data.bars.contains_key(symbol) for symbol in self.symbols.values()):
            return

        spy_close = float(data.bars[spy_symbol].close)
        aapl_close = float(data.bars[aapl_symbol].close)

        # Sells are evaluated before buys.  Each order is limited to the shares
        # recorded for the strategy that created the lot.
        if self.strategy_a_shares > 0 and self.spy_closes.is_ready:
            today_sma = sum(self.spy_closes[i] for i in range(100)) / 100.0
            yesterday_sma = sum(self.spy_closes[i] for i in range(1, 101)) / 100.0
            crossed_below = (
                self.spy_closes[1] >= yesterday_sma
                and self.spy_closes[0] < today_sma
            )
            if crossed_below:
                self.market_order(self.symbols["SPY"], -self.strategy_a_shares)
                self.strategy_a_shares = 0

        if (
            self.strategy_b_shares > 0
            and self.aapl_rsi.is_ready
            and float(self.aapl_rsi.current.value) > self.RSI_SELL_THRESHOLD
        ):
            self.market_order(self.symbols["AAPL"], -self.strategy_b_shares)
            self.strategy_b_shares = 0

        if self.strategy_a_shares == 0 and self.spy_closes.is_ready:
            today_sma = sum(self.spy_closes[i] for i in range(100)) / 100.0
            yesterday_sma = sum(self.spy_closes[i] for i in range(1, 101)) / 100.0
            crossed_above = (
                self.spy_closes[1] <= yesterday_sma
                and self.spy_closes[0] > today_sma
            )
            if crossed_above:
                shares = int((self.portfolio.total_portfolio_value * 0.40) / spy_close)
                if shares > 0:
                    self.market_order(self.symbols["SPY"], shares)
                    self.strategy_a_shares = shares

        if self.strategy_b_shares == 0 and self.aapl_red_streak >= 3:
            cash_to_invest = 20_000
            if self.portfolio.cash >= cash_to_invest:
                shares = int(cash_to_invest / aapl_close)
                if shares > 0:
                    self.market_order(self.symbols["AAPL"], shares)
                    self.strategy_b_shares = shares

