class IndependentSpyAaplStrategies(QCAlgorithm):
    """Two independent, privately accounted strategy lots."""

    RSI_THRESHOLD = 70

    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.add_equity(ticker, Resolution.DAILY).symbol

        self.spy_sma = self.sma(self.symbols["SPY"], 100, Resolution.DAILY)
        self.aapl_rsi = self.rsi(
            self.symbols["AAPL"], 14, MovingAverageType.WILDERS, Resolution.DAILY
        )
        self.aapl_closes = RollingWindow[float](4)

        self.previous_spy_close = None
        self.previous_spy_sma = None
        self.spy_lot = 0
        self.aapl_lot = 0
        self.spy_pending_quantity = 0
        self.aapl_pending_quantity = 0

        # Supplies the preceding values needed on the first eligible backtest bar.
        self.set_warm_up(101, Resolution.DAILY)

    def on_data(self, data: Slice):
        # Rolling market state is maintained continuously, independently of whether
        # all five bars needed for strategy evaluation are present.
        aapl_bar = data.bars.get(self.symbols["AAPL"])
        if aapl_bar is not None:
            self.aapl_closes.add(float(aapl_bar.close))

        spy_bar = data.bars.get(self.symbols["SPY"])
        current_spy_sma = float(self.spy_sma.current.value) if self.spy_sma.is_ready else None

        all_bars_present = all(data.bars.get(symbol) is not None for symbol in self.symbols.values())
        ready = (
            not self.is_warming_up
            and self.spy_sma.is_ready
            and self.aapl_rsi.is_ready
            and self.aapl_closes.is_ready
            and self.previous_spy_close is not None
            and self.previous_spy_sma is not None
        )

        if all_bars_present and ready:
            # All sells are evaluated before either independent strategy's buy.
            self._evaluate_spy_sell(float(spy_bar.close), current_spy_sma)
            self._evaluate_aapl_sell()
            self._evaluate_spy_buy(float(spy_bar.close), current_spy_sma)
            self._evaluate_aapl_buy(float(aapl_bar.close))

        # Preserve consecutive-day and crossing semantics across partial-data days.
        if spy_bar is not None and current_spy_sma is not None:
            self.previous_spy_close = float(spy_bar.close)
            self.previous_spy_sma = current_spy_sma

    def _evaluate_spy_sell(self, close, sma):
        if self.spy_lot <= 0 or self.spy_pending_quantity != 0:
            return
        crossed_below = self.previous_spy_close >= self.previous_spy_sma and close < sma
        if crossed_below:
            quantity = -self.spy_lot
            self.spy_pending_quantity = quantity
            self.market_order(self.symbols["SPY"], quantity, tag="Strategy A: SMA cross below")

    def _evaluate_aapl_sell(self):
        if self.aapl_lot <= 0 or self.aapl_pending_quantity != 0:
            return
        if float(self.aapl_rsi.current.value) > self.RSI_THRESHOLD:
            quantity = -self.aapl_lot
            self.aapl_pending_quantity = quantity
            self.market_order(self.symbols["AAPL"], quantity, tag="Strategy B: RSI above threshold")

    def _evaluate_spy_buy(self, close, sma):
        if self.spy_lot != 0 or self.spy_pending_quantity != 0:
            return
        crossed_above = self.previous_spy_close <= self.previous_spy_sma and close > sma
        if crossed_above:
            quantity = floor(0.40 * float(self.portfolio.total_portfolio_value) / close)
            if quantity > 0:
                self.spy_pending_quantity = quantity
                self.market_order(self.symbols["SPY"], quantity, tag="Strategy A: SMA cross above")

    def _evaluate_aapl_buy(self, close):
        if self.aapl_lot != 0 or self.aapl_pending_quantity != 0:
            return
        red_for_three_days = (
            self.aapl_closes[0] < self.aapl_closes[1]
            and self.aapl_closes[1] < self.aapl_closes[2]
            and self.aapl_closes[2] < self.aapl_closes[3]
        )
        cash_to_invest = 20_000
        if red_for_three_days and float(self.portfolio.cash) >= cash_to_invest:
            quantity = floor(cash_to_invest / close)
            if quantity > 0:
                self.aapl_pending_quantity = quantity
                self.market_order(self.symbols["AAPL"], quantity, tag="Strategy B: three red days")

    def on_order_event(self, order_event: OrderEvent):
        if order_event.status not in (OrderStatus.PARTIALLY_FILLED, OrderStatus.FILLED):
            if order_event.status in (OrderStatus.CANCELED, OrderStatus.INVALID):
                symbol = order_event.symbol
                if symbol == self.symbols["SPY"]:
                    self.spy_pending_quantity = 0
                elif symbol == self.symbols["AAPL"]:
                    self.aapl_pending_quantity = 0
            return

        filled = int(order_event.fill_quantity)
        if order_event.symbol == self.symbols["SPY"]:
            self.spy_lot += filled
            self.spy_pending_quantity -= filled
            if order_event.status == OrderStatus.FILLED:
                self.spy_pending_quantity = 0
        elif order_event.symbol == self.symbols["AAPL"]:
            self.aapl_lot += filled
            self.aapl_pending_quantity -= filled
            if order_event.status == OrderStatus.FILLED:
                self.aapl_pending_quantity = 0

