            if order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                if order_event.Symbol == self.symbols["SPY"]:
                    self.spy_pending = 0
                elif order_event.Symbol == self.symbols["AAPL"]:
                    self.aapl_pending = 0
            return

        fill = int(order_event.FillQuantity)
        if order_event.Symbol == self.symbols["SPY"]:
            self.spy_lot += fill
            self.spy_pending -= fill
            if self.spy_lot < 0:
                self.spy_lot = 0
        elif order_event.Symbol == self.symbols["AAPL"]:
            self.aapl_lot += fill
            self.aapl_pending -= fill
            if self.aapl_lot < 0:
                self.aapl_lot = 0

