    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1_000_000)

        self.symbols = {
            ticker: self.add_equity(ticker, Resolution.DAILY).symbol
            for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG")
        }

        self.spy_closes = RollingWindow[float](101)
        self.aapl_closes = RollingWindow[float](2)
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.WILDERS)

        self.spy_lot = 0
        self.aapl_lot = 0
        self.aapl_red_streak = 0
        self.rsi_threshold = 70.0

    def on_data(self, data: Slice):
        spy_bar = (
            data.bars[self.symbols["SPY"]]
            if data.bars.contains_key(self.symbols["SPY"])
            else None
        )
        if spy_bar is not None:
            self.spy_closes.add(float(spy_bar.close))

        aapl_bar = (
            data.bars[self.symbols["AAPL"]]
            if data.bars.contains_key(self.symbols["AAPL"])
            else None
        )
        if aapl_bar is not None:
            previous_aapl_close = (
                self.aapl_closes[0] if self.aapl_closes.count > 0 else None
            )
            if previous_aapl_close is None:
                self.aapl_red_streak = 0
            elif float(aapl_bar.close) < previous_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

            self.aapl_closes.add(float(aapl_bar.close))
            self.aapl_rsi.update(aapl_bar.end_time, aapl_bar.close)

        if any(not data.bars.contains_key(symbol) for symbol in self.symbols.values()):
            return

        self._run_spy_strategy()
        self._run_aapl_strategy(float(aapl_bar.close))

    def _run_spy_strategy(self):
        if not self.spy_closes.is_ready:
            return

        today_close = self.spy_closes[0]
        yesterday_close = self.spy_closes[1]
        today_sma = sum(self.spy_closes[i] for i in range(100)) / 100.0
        yesterday_sma = sum(self.spy_closes[i] for i in range(1, 101)) / 100.0

        if self.spy_lot > 0:
            if yesterday_close >= yesterday_sma and today_close < today_sma:
                self.market_order(self.symbols["SPY"], -self.spy_lot)
                self.spy_lot = 0
        elif yesterday_close <= yesterday_sma and today_close > today_sma:
            target_value = 0.40 * float(self.portfolio.total_portfolio_value)
            quantity = int(target_value / today_close)
            if quantity > 0:
                self.market_order(self.symbols["SPY"], quantity)
                self.spy_lot = quantity

    def _run_aapl_strategy(self, close):
        if not self.aapl_rsi.is_ready:
            return

        if self.aapl_lot > 0:
            if float(self.aapl_rsi.current.value) > self.rsi_threshold:
                self.market_order(self.symbols["AAPL"], -self.aapl_lot)
                self.aapl_lot = 0
        elif self.aapl_red_streak >= 3:
            cash_to_invest = 20_000.0
            if float(self.portfolio.cash) >= cash_to_invest:
                quantity = int(cash_to_invest // close)
                if quantity > 0:
                    self.market_order(self.symbols["AAPL"], quantity)
                    self.aapl_lot = quantity

