        self.set_cash(1_000_000)

        self.spy = self.add_equity("SPY", Resolution.DAILY).symbol
        self.aapl = self.add_equity("AAPL", Resolution.DAILY).symbol
        self.ibm = self.add_equity("IBM", Resolution.DAILY).symbol
        self.bac = self.add_equity("BAC", Resolution.DAILY).symbol
        self.aig = self.add_equity("AIG", Resolution.DAILY).symbol
        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        self.closes = {symbol: deque(maxlen=101) for symbol in self.symbols}
        self.previous_closes = {symbol: None for symbol in self.symbols}
        self.red_streaks = {symbol: 0 for symbol in self.symbols}

        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.WILDERS)
        self.spy_lot = 0
        self.aapl_lot = 0

    def on_data(self, data: Slice):
        todays_bars = {}
        for symbol in self.symbols:
            if symbol not in data.bars:
                continue

            bar = data.bars[symbol]
            todays_bars[symbol] = bar
            close = bar.close
            previous_close = self.previous_closes[symbol]

            if previous_close is not None and close < previous_close:
                self.red_streaks[symbol] += 1
            else:
                self.red_streaks[symbol] = 0

            self.closes[symbol].appendleft(close)
            self.previous_closes[symbol] = close

            if symbol == self.aapl:
                self.aapl_rsi.update(IndicatorDataPoint(bar.end_time, close))

        if len(todays_bars) != len(self.symbols):
            return

        spy_ready = len(self.closes[self.spy]) == 101
        aapl_ready = self.aapl_rsi.is_ready

        spy_crossed_below = False
        spy_crossed_above = False
        if spy_ready:
            spy_closes = self.closes[self.spy]
            today_sma = sum(list(spy_closes)[:100], Decimal(0)) / Decimal(100)
            yesterday_sma = sum(list(spy_closes)[1:101], Decimal(0)) / Decimal(100)
            today_close = spy_closes[0]
            yesterday_close = spy_closes[1]
            spy_crossed_above = (
                yesterday_close <= yesterday_sma and today_close > today_sma
            )
            spy_crossed_below = (
                yesterday_close >= yesterday_sma and today_close < today_sma
            )

        # All sells are evaluated before either independent strategy may buy.
        if self.spy_lot > 0 and spy_ready and spy_crossed_below:
            self.market_order(self.spy, -self.spy_lot)
            self.spy_lot = 0

        if (
            self.aapl_lot > 0
            and aapl_ready
            and self.aapl_rsi.current.value > self.RSI_THRESHOLD
        ):
            self.market_order(self.aapl, -self.aapl_lot)
            self.aapl_lot = 0

        if self.spy_lot == 0 and spy_ready and spy_crossed_above:
            quantity = self.calculate_order_quantity(self.spy, 0.40)
            if quantity > 0:
                self.market_order(self.spy, quantity)
                self.spy_lot = quantity

        if self.aapl_lot == 0 and aapl_ready and self.red_streaks[self.aapl] >= 3:
            cash_to_invest = Decimal(20_000)
            if self.portfolio.cash >= cash_to_invest:
                quantity = floor(cash_to_invest / todays_bars[self.aapl].close)
                if quantity > 0:
                    self.market_order(self.aapl, quantity)
                    self.aapl_lot = quantity

