class IndependentSpyAaplStrategies(QCAlgorithm):
    RSI_SELL_THRESHOLD = 70

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy_closes = RollingWindow[float](100)
        self.spy_previous_close = None
        self.spy_previous_sma = None

        self.aapl_previous_close = None
        self.aapl_red_streak = 0
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.spy_lot = 0
        self.aapl_lot = 0
        self.spy_order_pending = False
        self.aapl_order_pending = False

    def OnData(self, data: Slice):
        spy_bar = self._bar(data, self.symbols["SPY"])
        aapl_bar = self._bar(data, self.symbols["AAPL"])

        spy_close = None
        spy_sma = None
        if spy_bar is not None:
            spy_close = float(spy_bar.Close)
            self.spy_closes.Add(spy_close)
            if self.spy_closes.IsReady:
                spy_sma = sum(self.spy_closes) / 100.0

        aapl_close = None
        if aapl_bar is not None:
            aapl_close = float(aapl_bar.Close)
            if self.aapl_previous_close is not None:
                if aapl_close < self.aapl_previous_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
            self.aapl_rsi.Update(aapl_bar.EndTime, aapl_close)

        all_bars_present = all(
            self._bar(data, symbol) is not None for symbol in self.symbols.values()
        )

        if all_bars_present:
            self._evaluate_spy(spy_close, spy_sma)
            self._evaluate_aapl(aapl_close)

        if spy_bar is not None:
            self.spy_previous_close = spy_close
            self.spy_previous_sma = spy_sma
        if aapl_bar is not None:
            self.aapl_previous_close = aapl_close

    def _evaluate_spy(self, close, sma):
        if (
            sma is None
            or self.spy_previous_sma is None
            or self.spy_previous_close is None
            or self.spy_order_pending
        ):
            return

        if self.spy_lot > 0:
            crossed_below = (
                self.spy_previous_close >= self.spy_previous_sma and close < sma
            )
            if crossed_below:
                self.spy_order_pending = True
                self.MarketOrder(self.symbols["SPY"], -self.spy_lot, tag="Strategy A")
            return

        crossed_above = (
            self.spy_previous_close <= self.spy_previous_sma and close > sma
        )
        if crossed_above:
            quantity = int((0.40 * float(self.Portfolio.TotalPortfolioValue)) // close)
            if quantity > 0:
                self.spy_order_pending = True
                self.MarketOrder(self.symbols["SPY"], quantity, tag="Strategy A")

    def _evaluate_aapl(self, close):
        if self.aapl_order_pending or not self.aapl_rsi.IsReady:
            return

        if self.aapl_lot > 0:
            if float(self.aapl_rsi.Current.Value) > self.RSI_SELL_THRESHOLD:
                self.aapl_order_pending = True
                self.MarketOrder(
                    self.symbols["AAPL"], -self.aapl_lot, tag="Strategy B"
                )
            return

        if self.aapl_red_streak >= 3:
            cash = float(self.Portfolio.CashBook["USD"].Amount)
            if cash >= 20_000:
                quantity = int(20_000 // close)
                if quantity > 0:
                    self.aapl_order_pending = True
                    self.MarketOrder(
                        self.symbols["AAPL"], quantity, tag="Strategy B"
                    )

    def OnOrderEvent(self, order_event: OrderEvent):
        order = self.Transactions.GetOrderById(order_event.OrderId)
        if order is None:
            return

        if order.Tag == "Strategy A":
            if order_event.FillQuantity != 0:
                self.spy_lot = max(0, self.spy_lot + int(order_event.FillQuantity))
            if order_event.Status in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid,
            ):
                self.spy_order_pending = False

        elif order.Tag == "Strategy B":
            if order_event.FillQuantity != 0:
                self.aapl_lot = max(0, self.aapl_lot + int(order_event.FillQuantity))
            if order_event.Status in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid,
            ):
                self.aapl_order_pending = False

    @staticmethod
    def _bar(data, symbol):
        return data.Bars[symbol] if data.Bars.ContainsKey(symbol) else None

