class IndependentSpyAaplStrategies(QCAlgorithm):
    """Two independent, privately tracked strategy lots."""

    RSI_SELL_THRESHOLD = 70

    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1_000_000)

        self.symbols = {}
        for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG"):
            self.symbols[ticker] = self.add_equity(ticker, Resolution.DAILY).symbol

        self.spy_sma = self.sma(self.symbols["SPY"], 100, Resolution.DAILY)
        self.aapl_rsi = self.rsi(
            self.symbols["AAPL"], 14, MovingAverageType.WILDERS, Resolution.DAILY
        )

        self.previous_spy_close = None
        self.previous_spy_sma = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.spy_lot = 0
        self.aapl_lot = 0

    def on_data(self, data: Slice):
        all_bars_present = all(
            data.bars.contains_key(symbol) for symbol in self.symbols.values()
        )
        spy_bar = (
            data.bars[self.symbols["SPY"]]
            if data.bars.contains_key(self.symbols["SPY"])
            else None
        )
        aapl_bar = (
            data.bars[self.symbols["AAPL"]]
            if data.bars.contains_key(self.symbols["AAPL"])
            else None
        )

        # Preserve market-state history even on a day when rules must be skipped.
        if spy_bar is None or aapl_bar is None:
            if spy_bar is not None:
                self.previous_spy_close = float(spy_bar.close)
                self.previous_spy_sma = (
                    float(self.spy_sma.current.value) if self.spy_sma.is_ready else None
                )
            if aapl_bar is not None:
                aapl_close = float(aapl_bar.close)
                if self.previous_aapl_close is not None and aapl_close < self.previous_aapl_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0
                self.previous_aapl_close = aapl_close
            return

        spy_close = float(spy_bar.close)
        aapl_close = float(aapl_bar.close)

        if self.previous_aapl_close is None:
            self.aapl_red_streak = 0
        elif aapl_close < self.previous_aapl_close:
            self.aapl_red_streak += 1
        else:
            self.aapl_red_streak = 0

        indicators_ready = self.spy_sma.is_ready and self.aapl_rsi.is_ready
        spy_sma_today = float(self.spy_sma.current.value) if self.spy_sma.is_ready else None

        if all_bars_present and indicators_ready and self.previous_spy_sma is not None:
            # Sells are evaluated before buys. Each ticker has exactly one private lot.
            if self.spy_lot > 0:
                crossed_below = (
                    self.previous_spy_close >= self.previous_spy_sma
                    and spy_close < spy_sma_today
                )
                if crossed_below:
                    self.market_order(self.symbols["SPY"], -self.spy_lot)
                    self.spy_lot = 0

            if self.aapl_lot > 0:
                if float(self.aapl_rsi.current.value) > self.RSI_SELL_THRESHOLD:
                    self.market_order(self.symbols["AAPL"], -self.aapl_lot)
                    self.aapl_lot = 0

            if self.spy_lot == 0:
                crossed_above = (
                    self.previous_spy_close <= self.previous_spy_sma
                    and spy_close > spy_sma_today
                )
                if crossed_above:
                    quantity = int((0.40 * float(self.portfolio.total_portfolio_value)) // spy_close)
                    if quantity > 0:
                        self.market_order(self.symbols["SPY"], quantity)
                        self.spy_lot = quantity

            if self.aapl_lot == 0 and self.aapl_red_streak >= 3:
                cash_to_invest = 20_000
                if float(self.portfolio.cash) >= cash_to_invest:
                    quantity = int(cash_to_invest // aapl_close)
                    if quantity > 0:
                        self.market_order(self.symbols["AAPL"], quantity)
                        self.aapl_lot = quantity

        self.previous_spy_close = spy_close
        self.previous_spy_sma = spy_sma_today
        self.previous_aapl_close = aapl_close

