class IndependentSpyAaplStrategies(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {
            ticker: self.AddEquity(ticker, Resolution.Daily).Symbol
            for ticker in ("SPY", "AAPL", "IBM", "BAC", "AIG")
        }

        self.spy_closes = deque(maxlen=101)
        self.aapl_previous_close = None
        self.aapl_red_streak = 0
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)
        self.rsi_threshold = Decimal(70)

        self.spy_lot = 0
        self.aapl_lot = 0
        self.spy_pending = False
        self.aapl_pending = False

    def OnData(self, data: Slice):
        spy = self.symbols["SPY"]
        aapl = self.symbols["AAPL"]

        if data.Bars.ContainsKey(spy):
            self.spy_closes.append(Decimal(data.Bars[spy].Close))

        if data.Bars.ContainsKey(aapl):
            aapl_close = Decimal(data.Bars[aapl].Close)
            if self.aapl_previous_close is None:
                self.aapl_red_streak = 0
            elif aapl_close < self.aapl_previous_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0
            self.aapl_previous_close = aapl_close
            self.aapl_rsi.Update(data.Bars[aapl].EndTime, aapl_close)

        if any(not data.Bars.ContainsKey(symbol) for symbol in self.symbols.values()):
            return

        if len(self.spy_closes) < 101 or not self.aapl_rsi.IsReady:
            return

        spy_close = self.spy_closes[-1]
        spy_previous_close = self.spy_closes[-2]
        spy_sma = sum(list(self.spy_closes)[-100:]) / Decimal(100)
        spy_previous_sma = sum(list(self.spy_closes)[:100]) / Decimal(100)

        spy_crossed_above = (
            spy_previous_close <= spy_previous_sma and spy_close > spy_sma
        )
        spy_crossed_below = (
            spy_previous_close >= spy_previous_sma and spy_close < spy_sma
        )

        # Sells are evaluated before buys.
        if self.spy_lot > 0 and not self.spy_pending and spy_crossed_below:
            self.spy_pending = True
            self.MarketOrder(spy, -self.spy_lot, tag="Strategy A sell")

        if (
            self.aapl_lot > 0
            and not self.aapl_pending
            and self.aapl_rsi.Current.Value > self.rsi_threshold
        ):
            self.aapl_pending = True
            self.MarketOrder(aapl, -self.aapl_lot, tag="Strategy B sell")

        if self.spy_lot == 0 and not self.spy_pending and spy_crossed_above:
            quantity = self.CalculateOrderQuantity(spy, 0.40)
            if quantity > 0:
                self.spy_pending = True
                self.MarketOrder(spy, quantity, tag="Strategy A buy")

        if (
            self.aapl_lot == 0
            and not self.aapl_pending
            and self.aapl_red_streak >= 3
            and self.Portfolio.Cash >= Decimal(20_000)
        ):
            quantity = floor(Decimal(20_000) / Decimal(data.Bars[aapl].Close))
            if quantity > 0:
                self.aapl_pending = True
                self.MarketOrder(aapl, quantity, tag="Strategy B buy")

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.Status not in (OrderStatus.Filled, OrderStatus.Canceled, OrderStatus.Invalid):
            return

        order = self.Transactions.GetOrderById(order_event.OrderId)
        if order.Symbol == self.symbols["SPY"]:
            if order_event.Status == OrderStatus.Filled:
                self.spy_lot += int(order_event.FillQuantity)
            self.spy_pending = False
        elif order.Symbol == self.symbols["AAPL"]:
            if order_event.Status == OrderStatus.Filled:
                self.aapl_lot += int(order_event.FillQuantity)
            self.aapl_pending = False

